#include "ResultScene.hpp"
#include <algorithm>
namespace th075 {
void ResultScene::initialize(FighterActor& first,const FighterActor& other,const RoundRules& rules,const BattleSession& session,i16 sessionCombo){*this=ResultScene{};base=other.stageClearBonus;capture=rules.awardedSpellTime;captureMultiplier=float(double(capture)/double(session.maximumStoryBonus)+1.0);combo=sessionCombo;comboMultiplier=float(double(combo)/100.0+1.0);lives=i32(first.combat.health)+(i32(rules.remainingLives)-1+i8(first.combat.spellPhase))*10000;lifeMultiplier=float(double(first.combat.health)/10000.0+i32(rules.remainingLives)+i8(first.combat.spellPhase)-1.0);first.combat.health=first.combat.maximumHealth=10000;}
u16 ResultScene::advance(bool confirm,FighterActor& first,RoundRules& rules,BattleSession& session,u8 difficulty,u8 nextStage,u8 replayStages,ResultSignals& signals,bool practice){signals.render_result();signals.present_result();const auto difficultyScale=[&](i32 n){constexpr double factors[4]{.5,1,1.5,2};return difficulty<4?i32(double(n)*factors[difficulty]):n;};if(confirm){if(i8(phase)<6){slide.fill(0);pending=base;pending=i32(double(pending)*double(comboMultiplier));pending=i32(double(pending)*double(captureMultiplier));pending=i32(double(pending)*double(lifeMultiplier));pending=difficultyScale(pending);first.score=increment_wrapped(first.score,pending);pending=0;phase=7;timer=400;}else if(phase!=6){if(rules.highScore<u32(first.score))rules.highScore=u32(first.score);if(session.replayMode==2&&replayStages<=u8(session.roundIndex)){signals.select_music(40);signals.fade_music(-10000,-160,1,1);return 0x2205;}if(practice){signals.select_music(40);signals.fade_music(-10000,-160,1,1);session.replayDisposition=-1;return 0x2207;}if(i8(nextStage)>7){if(session.replayMode==2){signals.select_music(40);signals.fade_music(-10000,-160,1,1);return 0x2205;}return 0x1108;}return 0x2301;}else{first.score=increment_wrapped(first.score,pending);timer=400;pending=0;phase=7;}}
 if(nextStage==10)backgroundScale=1;else if(double(backgroundScale)<=double(.4f))backgroundScale=.4f;else backgroundScale=float(double(backgroundScale)-double(.01f));if(alpha<255)alpha=u8(alpha+5);else {timer=increment_wrapped(timer,1);if(i8(phase)<5&&slide[phase]>0)slide[phase]=i16(slide[phase]-30);}
 if(timer==30){phase=1;pending=increment_wrapped(pending,base);signals.sound(45);}else if(timer==60){phase=2;pending=i32(double(pending)*double(comboMultiplier));signals.sound(45);}else if(timer==90){phase=3;pending=i32(double(pending)*double(captureMultiplier));signals.sound(45);}else if(timer==120){phase=4;pending=i32(double(pending)*double(lifeMultiplier));signals.sound(45);}else if(timer==180){phase=5;signals.sound(40);pending=difficultyScale(pending);}else if(timer==300){payoutStep=std::max(1234,pending/600);phase=6;}
 if(phase==6){if(payoutStep<pending){pending=subtract_wrapped(pending,payoutStep);first.score=increment_wrapped(first.score,payoutStep);soundCycle=u8((i8(soundCycle)+1)%3);if(soundCycle==0)signals.sound(49);}else{first.score=increment_wrapped(first.score,pending);pending=0;phase=7;}}return 6;
}
}
